export const wsIndexScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string, a: Record<string, unknown> = {}, x: string[] = []): string => `<script>
// BUG FIX: these handlers previously called .addEventListener() directly on the result of
// getElementById(). The per-piece send controls only render for non-Workshop-Staff users, so for
// a Workshop Staff login getElementById('selectAllPendingBtn') returned null and the whole script
// block threw a TypeError on page load — silently killing every other handler below it too.
// Each lookup is now guarded. No behaviour changes for users who do see the controls.
(function () {
  var selectAllBtn = document.getElementById('selectAllPendingBtn');
  var clearBtn = document.getElementById('clearSelectionBtn');
  var challanForm = document.getElementById('challanForm');

  if (selectAllBtn) selectAllBtn.addEventListener('click', function () {
    document.querySelectorAll('.row-check').forEach(function (cb) { cb.checked = true; });
  });
  if (clearBtn) clearBtn.addEventListener('click', function () {
    document.querySelectorAll('.row-check').forEach(function (cb) { cb.checked = false; });
  });
  if (challanForm) challanForm.addEventListener('submit', function (e) {
    if (document.querySelectorAll('.row-check:checked').length === 0) { e.preventDefault(); alert('Select at least one Pending item to send to the workshop.'); }
  });

  var lgSelectAllBtn = document.getElementById('lgSelectAllBtn');
  var lgClearBtn = document.getElementById('lgClearBtn');
  var laundryForm = document.getElementById('laundryChallanForm');

  if (lgSelectAllBtn) lgSelectAllBtn.addEventListener('click', function () {
    document.querySelectorAll('.lg-row-check').forEach(function (cb) { cb.checked = true; });
  });
  if (lgClearBtn) lgClearBtn.addEventListener('click', function () {
    document.querySelectorAll('.lg-row-check').forEach(function (cb) { cb.checked = false; });
  });
  if (laundryForm) laundryForm.addEventListener('submit', function (e) {
    if (document.querySelectorAll('.lg-row-check:checked').length === 0) { e.preventDefault(); alert('Select at least one Laundry garment to send to the workshop.'); }
  });
})();
</script>`;
